// Key generation
public class KeyGenerator {
    private readonly SnowflakeIdGenerator _idGenerator;

    public string GenerateKey() {
        var id = _idGenerator.NextId();
        return Base62Encode(id);
    }

    private string Base62Encode(long id) {
        const string chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
        var result = new StringBuilder();
        while (id > 0) {
            result.Insert(0, chars[(int)(id % 62)]);
            id /= 62;
        }
        return result.ToString();
    }
}

// Redirect with caching
public async Task<IActionResult> Redirect(string shortCode) {
    var url = await _cache.GetOrSetAsync(shortCode, 
        () => _db.UrlMappings.FindAsync(shortCode));
    return Redirect(url);
}
